from pathlib import Path
import re
errors = []
for source in Path("project").rglob("*.md"):
    for target in re.findall(r"\]\(([^)]+)\)", source.read_text()):
        if not (source.parent / target).is_file():
            errors.append(str(source) + ": " + target)
print("\n".join(errors) if errors else "record links passed")
raise SystemExit(bool(errors))

